package com.german_software_engineers.trainerapp;

import android.os.Bundle;
import android.support.design.widget.FloatingActionButton;
import android.support.design.widget.Snackbar;
import android.support.v7.app.AppCompatActivity;
import android.support.v7.widget.Toolbar;
import android.util.Log;
import android.view.View;
import android.widget.TextView;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;

public class InfoActivity extends AppCompatActivity {

    private static final String TAG = "InfoActivity";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_info);
        Toolbar toolbar = (Toolbar) findViewById(R.id.toolbar);
        setSupportActionBar(toolbar);

        FloatingActionButton fab = (FloatingActionButton) findViewById(R.id.fab);
        fab.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                Snackbar.make(view, "Contact us on GitHub", Snackbar.LENGTH_LONG)
                        .setAction("Action", null).show();
            }
        });
        getSupportActionBar().setDisplayHomeAsUpEnabled(true);

        // The complete license does not fit into a single string resource,
        // therefore it is shipped as a raw resource and read here.
        TextView licenseView = (TextView) findViewById(R.id.license_text);
        licenseView.setText(readLicense());
    }

    /**
     * Reads the complete license text from res/raw/license.txt.
     *
     * @return the full license text, or a fallback message if it cannot be read.
     */
    private String readLicense() {
        InputStream inputStream = null;
        BufferedReader reader = null;
        try {
            inputStream = getResources().openRawResource(R.raw.license);
            reader = new BufferedReader(new InputStreamReader(inputStream, "UTF-8"));
            StringBuilder licenseText = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                licenseText.append(line).append('\n');
            }
            return licenseText.toString();
        } catch (IOException e) {
            Log.e(TAG, "Could not read the license text", e);
            return getString(R.string.license_unavailable);
        } finally {
            closeQuietly(reader);
            closeQuietly(inputStream);
        }
    }

    private static void closeQuietly(java.io.Closeable closeable) {
        if (closeable != null) {
            try {
                closeable.close();
            } catch (IOException e) {
                Log.w(TAG, "Could not close stream", e);
            }
        }
    }
}
